feed:
{% for post in posts %}
  {% if post.summary %}{% set summary = post.summary %}{% else %}{% set summary = post.title ~ "..." %}{% endif %}
  {{ summary }}
{% endfor %}
{% if showFooter %}
  {% if lang == "fr" %}{% set footer = "Fin" %}{% else %}{% set footer = "End" %}{% endif %}
  {{ footer }}
{% endif %}
